        if calls["n"] == 3:  # submit check, envelope a, then cancel on b
            assert _cancel(client, job_id).status_code == 200
        return real_load()

    monkeypatch.setattr(app_module, "load_keyring", cancelling_load)
    runner.run(job_id)

    shown = _get_job(client, job_id).json()
    assert shown["status"] == "cancelled"
